import { gsap } from 'gsap';
import {
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  mix,
  vec3,
  vec2,
  color,
  fract,
  sin,
  dot,
  smoothstep,
  length,
  texture,
  float,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DoubleSide } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.userData.handlers = {};

  const CARD_W = 2.4;
  const CARD_H = 1.5;

  // ---------------------------------------------------------------
  // Backdrop: engineered gradient surface (ink -> surface, vertical)
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(CARD_W + 0.5, CARD_H + 0.5);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const gY = uv().y;
  const inkColor = color(palette.ink);
  const surfaceColor = color(palette.surface);
  backdropMat.colorNode = mix(surfaceColor, inkColor, smoothstep(0.0, 1.0, gY));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.06);
  group.add(backdrop);

  // ---------------------------------------------------------------
  // Machined-metal frame (extruded bevel) around the card image
  // ---------------------------------------------------------------
  const frameGeo = new BoxGeometry(CARD_W + 0.12, CARD_H + 0.12, 0.07);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(palette.ink),
    metalness: 0.52,
    roughness: 0.55,
    clearcoat: 0.18,
    clearcoatRoughness: 0.4,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.035);
  group.add(frame);

  // thin accent edge line (10% of frame max)
  const edgeGeo = new PlaneGeometry(CARD_W + 0.14, 0.02);
  const edgeMat = new MeshBasicNodeMaterial({ color: new THREE.Color(palette.accent) });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -CARD_H / 2 - 0.06, 0.001);
  group.add(edge);

  // ---------------------------------------------------------------
  // Contact shadow (radial falloff) grounding the card
  // ---------------------------------------------------------------
  const shadowGeo = new PlaneGeometry((CARD_W + 0.12) * 1.35, (CARD_H + 0.12) * 1.15);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new THREE.Color('#000000'),
    transparent: true,
    depthWrite: false,
  });
  const suv = uv().sub(vec2(0.5, 0.5));
  const dist = length(suv);
  const shadowAlpha = smoothstep(0.55, 0.0, dist).mul(0.5);
  shadowMat.opacityNode = shadowAlpha;
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -CARD_H / 2 - 0.15, -0.07);
  group.add(contactShadow);

  // ---------------------------------------------------------------
  // Image plane with subtle grain overlay
  // ---------------------------------------------------------------
  const imgGeo = new PlaneGeometry(CARD_W, CARD_H);
  const imgMat = new MeshBasicNodeMaterial();
  // fallback color before texture resolves
  imgMat.colorNode = mix(color(palette.surface), color(palette.ink), uv().y);
  const imgPlane = new Mesh(imgGeo, imgMat);
  imgPlane.position.set(0, 0, 0.001);
  group.add(imgPlane);

  let loadedTexture = null;

  const grainNode = fract(
    sin(dot(uv().mul(4000.0), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainOffset = grainNode.sub(0.5).mul(0.035);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      const texSample = texture(tex);
      imgMat.colorNode = texSample.rgb.add(vec3(grainOffset, grainOffset, grainOffset));
      imgMat.needsUpdate = true;
    }).catch(() => {
      // keep gradient fallback on failure
    });
  }

  // ---------------------------------------------------------------
  // Node-local accent rim light (signal red), small + capped
  // ---------------------------------------------------------------
  const rimLight = new THREE.PointLight(new THREE.Color(palette.accent), 0.7, 4.0);
  rimLight.position.set(0.8, 0.6, 1.2);
  group.add(rimLight);

  // ---------------------------------------------------------------
  // Entrance: weighted-settle, no idle perpetual motion (static composition)
  // ---------------------------------------------------------------
  group.scale.set(0.97, 0.97, 0.97);
  group.position.y += 0.0; // adapter controls final position; only animate local offset via scale/opacity proxies

  const settleState = { s: 0.97 };
  const tl = gsap.timeline();
  tl.to(settleState, {
    s: 1.0,
    duration: 0.9,
    ease: 'power4.out',
    onUpdate: () => {
      group.scale.setScalar(settleState.s);
    },
  });
  tl.from(
    [frame.position, imgPlane.position],
    {
      z: '+=0.15',
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  group.userData.cleanup = () => {
    tl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    group.remove(rimLight);
  };

  return group;
}
